src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = [r for r in range(h) if grid[r][0] == 1 and grid[r][w - 1] == 1]
    cols = [c for c in range(w) if grid[0][c] == 1 and grid[h - 1][c] == 1]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            if any(y in rows or x in cols for y, x in component):
                for y, x in component:
                    out[y][x] = 1
    for r in rows:
        for x in range(w):
            out[r][x] = 1
    for c in cols:
        for y in range(h):
            out[y][c] = 1
    return out
